INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16401, 'Ecclesiastes 4:10', 'Ecclesiastes', 4, 10, '&nbsp;کۀ په هغوئ کښې يو کس وغورزيږى، نو هغه دوېم به يې راپاڅوى، خو کۀ څوک يواځې وى او وغورزيږى، نو په هغۀ افسوس، ځکه چې داسې به څوک نۀ وى چې هغه راپاڅوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16402, 'Ecclesiastes 4:11', 'Ecclesiastes', 4, 11, '&nbsp;هم داسې، کۀ يخنى وى او دوه کسان يو ځائ څملى نو ګرم به شى، خو يو کس به يواځې څنګه ځان ګرم کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16403, 'Ecclesiastes 4:12', 'Ecclesiastes', 4, 12, '&nbsp;خو کۀ يو کس يواځې وى نو شکست به وخورى، خو کۀ دوه کسه يو ځائ شى نو مقابله کولے شى. د درېو مزو پړے په آسانه نۀ شليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16404, 'Ecclesiastes 4:13', 'Ecclesiastes', 4, 13, '&nbsp;‏يو غريب خو هوښيار ځوان ښۀ دے د هغه بوډا او کم عقل بادشاه نه، څوک چې د چا نصيحت ته غوږ نۀ اېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16405, 'Ecclesiastes 4:14', 'Ecclesiastes', 4, 14, '&nbsp;دغه ځوان د غريبۍ نه د کاميابۍ طرف ته تلے شى، اګر کۀ هغه قېدى وو خو هغه بيا هم بادشاه جوړېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16406, 'Ecclesiastes 4:15', 'Ecclesiastes', 4, 15, '&nbsp;بيا ما وکتل چې خلق يو بل ځوان پسې روان وُو، څوک به چې د هغۀ په ځائ بادشاه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16407, 'Ecclesiastes 4:16', 'Ecclesiastes', 4, 16, '&nbsp;بې‌شمېره خلق د هغۀ نه ګېرچاپېره وُو، خو بيا يوه بله پيړۍ راوچته شوه او هغه يې هم رد کړو. نو دا څيزونه بې‌معنې دى، دا داسې دى لکه چې څوک هوا پسې منډې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16408, 'Ecclesiastes 5:1', 'Ecclesiastes', 5, 1, '&nbsp;کله چې تۀ د خُدائ پاک کور ته ځې نو چې څۀ کوې هغه ډېر خيال سره کوه. د اورېدلو دپاره د خُدائ پاک حضور ته تلل بهتر دى د کم عقلانو په شان د قربانو پېش کولو نه، خُدائ پاک ته بې‌سوچه نذرانې پېش کول بدعملى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16409, 'Ecclesiastes 5:2', 'Ecclesiastes', 5, 2, '&nbsp;د خُدائ پاک په حضور کښې په خبرو کولو کښې تېزى مۀ کوه، د هغۀ په وړاندې په څۀ بيان کولو کښې جلدى مۀ کوه. ځکه چې هغه په آسمان کښې دے او تۀ په زمکه باندې يې، نو د ضرورت نه زياتې خبرې مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16410, 'Ecclesiastes 5:3', 'Ecclesiastes', 5, 3, '&nbsp;څومره چې تۀ پرېشانه يې، نو هغه هومره به خراب خوبونه وينې او چې څومره زياتې خبرې کوې، نو هغه هومره به کم عقلې خبرې درنه وځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16411, 'Ecclesiastes 5:4', 'Ecclesiastes', 5, 4, '&nbsp;کله چې تۀ خُدائ پاک ته يوه منښته ومنې، نو چې څومره زر کېدے شى نو دا منښته پوره کوه. هغه د کم عقلو خلقو نه خوشحال نۀ وى. کومه منښته چې ومنې نو هغه سر ته رسوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16412, 'Ecclesiastes 5:5', 'Ecclesiastes', 5, 5, '&nbsp;چې يوه منښته ومنې او سر ته يې نۀ رسوې نو د داسې منښتې د منلو نه نۀ منل ښۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16413, 'Ecclesiastes 5:6', 'Ecclesiastes', 5, 6, '&nbsp;د خپلو خبرو په وجه ځان مۀ ګناهګارَوه، او اِمام ته مۀ وايه چې ما په غلطۍ سره منښته منلې وه. نو په دې وئيلو سره خُدائ پاک مۀ غصه کوه چې ستا ټول محنت مشقت تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16414, 'Ecclesiastes 5:7', 'Ecclesiastes', 5, 7, '&nbsp;خو ډېر خوبونه او ډيرې خبرې بې‌معنې دى، په ځائ د دې د خُدائ پاک نه وويرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16415, 'Ecclesiastes 5:8', 'Ecclesiastes', 5, 8, '&nbsp;چې کله تۀ وګورې چې په يوه علاقه کښې غريبانانو باندې ظلم زياتے کيږى او هغوئ ته صداقت او اِنصاف او د هغوئ حقُونه نۀ ملاويږى نو په دې باندې مۀ حېرانېږه. د هر آفسر دپاسه بل آفسر وى او د هغوئ د سر دپاسه نور آفسران وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16416, 'Ecclesiastes 5:9', 'Ecclesiastes', 5, 9, '&nbsp;تر دې چې بادشاه هم د دې مُلک نه خپل مفاد حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16417, 'Ecclesiastes 5:10', 'Ecclesiastes', 5, 10, '&nbsp;څوک چې د پېسو سره مينه لرى، نو هغه به هيڅکله په پېسو موړ نۀ شى. څوک چې د دولت سره مينه لرى، نو هغه به هيڅکله په دولت موړ نۀ شى. ځکه چې دا هم بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16418, 'Ecclesiastes 5:11', 'Ecclesiastes', 5, 11, '&nbsp;چې څومره پېسې زياتې وى، نو دومره به د دې د خوړلو خلق هم زيات وى. دغه دولت ته د کتلو نه سېوا مالِک ته څۀ حاصل شول؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16419, 'Ecclesiastes 5:12', 'Ecclesiastes', 5, 12, '&nbsp;محنت مزدورۍ کولو والا کۀ لږه خوړلى وى او کۀ ډېره خو ښۀ د سکون خوب کوى، خو د مالداره سړى دولت هغه خوب ته نۀ پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16420, 'Ecclesiastes 5:13', 'Ecclesiastes', 5, 13, '&nbsp;ما په مخ د زمکې يو بل ډېر خراب کار ليدلے دے. څوک چې د ځان دپاره پېسې جمع کوى نو هغه وروستو هم د هغوئ دپاره د نقصان باعث شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16421, 'Ecclesiastes 5:14', 'Ecclesiastes', 5, 14, '&nbsp;ځکه چې هغوئ دا ټولې پېسې په يو ناکاميابه کاروبار کښې بائيلى او په آخر کښې د هغوئ سره هيڅ هم نۀ وى چې خپلو بچو ته يې پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16422, 'Ecclesiastes 5:15', 'Ecclesiastes', 5, 15, '&nbsp;لکه څنګه چې ماشوم دې دُنيا ته لغړ او خالى لاسونه راځى، هم داسې به دې دُنيا نه خالى لاسونه ځى. هغه د ټول محنت باوجود هم د ځان سره هيڅ هم نۀ شى وړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16423, 'Ecclesiastes 5:16', 'Ecclesiastes', 5, 16, '&nbsp;دا هم ډېره د افسوس خبره ده، چې څنګه انسان دُنيا ته راځى نو هغه شان ځى. هغۀ فائده څۀ وکړه؟ چې عبث هوا پسې يې منډې ووهلې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16424, 'Ecclesiastes 5:17', 'Ecclesiastes', 5, 17, '&nbsp;هغۀ خپل ټول ژوند په تيارۀ، په پرېشانۍ، په غصه او په بيمارۍ کښې تېر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16425, 'Ecclesiastes 5:18', 'Ecclesiastes', 5, 18, '&nbsp;نو زۀ دې نتيجې ته ورسېدم چې د انسان دپاره ښۀ او بهتره دا ده چې څومره ورځې خُدائ پاک هغۀ له ورکړې دى په هغې کښې خوراک څښاک کوى او په مخ د زمکې د خپل سخت محنت نه خوند اخلى. ځکه چې هم دا زمونږه اجر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16426, 'Ecclesiastes 5:19', 'Ecclesiastes', 5, 19, '&nbsp;کۀ خُدائ پاک چا له دولت او جائيداد ورکوى او د دې قابل يې جوړوى چې د دې نه خوند واخلى، او دا خپل نصيب وګڼى او محنت سره سره خوشحاله هم وى، نو دا د خُدائ پاک د طرف نه اِنعام دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16427, 'Ecclesiastes 5:20', 'Ecclesiastes', 5, 20, '&nbsp;حقيقت کښې خُدائ پاک هغوئ په خوشحالۍ کښې دومره مصروف ساتى چې هغوئ سره د اندېښنو دپاره وخت هم نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16428, 'Ecclesiastes 6:1', 'Ecclesiastes', 6, 1, '&nbsp;په مخ د زمکې ما يوه بله خرابه خبره ليدلې ده او دا په انسان باندې يو دروند بوج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16429, 'Ecclesiastes 6:2', 'Ecclesiastes', 6, 2, '&nbsp;دا د هغه کس خبره ده چا له چې خُدائ پاک مال دولت، عزت او جائيداد ورکړى او هغه هر څۀ ورکړى چې د هغۀ زړۀ يې غواړى، خو خُدائ پاک يې د دې په خوند پوهه نۀ کړى او د هغۀ په ځائ يو پردے کس په دې باندې مزې وکړى. دا بې‌معنې دى او لوئ مصيبت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16430, 'Ecclesiastes 6:3', 'Ecclesiastes', 6, 3, '&nbsp;کۀ د يو سړى سل بچى وى او تر بوډاتوبه پورې ژوندے وى، خو کۀ په ژوند کښې څۀ خوشحالى ونۀ وينى او په عزت سره دفن نۀ شى نو زۀ خو به دا وايم چې د دۀ نه خو هغه ماشوم ښۀ دے چې مړ پېدا شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16431, 'Ecclesiastes 6:4', 'Ecclesiastes', 6, 4, '&nbsp;د داسې پېدائشى مړ ماشوم دُنيا ته راتګ او تګ بې‌معنې دے، مرګ د هغۀ شناخت زمونږ نه پټ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16432, 'Ecclesiastes 6:5', 'Ecclesiastes', 6, 5, '&nbsp;اګر چې هغۀ نمر هم نۀ دے ليدلے او نۀ ورته دا پته لګېدلې ده چې ژوند څنګه وى، خو بيا هم هغۀ ته د هغه مالداره سړى نه زيات آرام حاصل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16433, 'Ecclesiastes 6:6', 'Ecclesiastes', 6, 6, '&nbsp;فرض کړه کۀ هغه دوه زره کاله ژوندے وى خو چې په ژوند کښې يې څۀ خوشحالى نۀ وى، نو څۀ فائده؟ آخر مرګ خو هر ژوندى له شته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16434, 'Ecclesiastes 6:7', 'Ecclesiastes', 6, 7, '&nbsp;انسان ټول محنت د خوراک پېدا کولو دپاره کوى، خو د هغۀ لوږه هيڅکله نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16435, 'Ecclesiastes 6:8', 'Ecclesiastes', 6, 8, '&nbsp;هوښيار کس د کم عقل نه په څۀ فائده مند وى؟ کۀ غريب کس خلقو سره مناسب سلوک کوى نو په دې کښې د هغۀ دپاره څۀ فائده ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16436, 'Ecclesiastes 6:9', 'Ecclesiastes', 6, 9, '&nbsp;څۀ چې مونږ سره وى د هغې نه خوند اخستل ښۀ دى په ځائ د دې چې د هغه څيزونو خواهش ولرو چې مونږ سره نۀ وى. دا بې‌معنې دى، او دا داسې دى لکه چې هوا پسې منډې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16437, 'Ecclesiastes 6:10', 'Ecclesiastes', 6, 10, '&nbsp;هر څۀ چې کيږى هغه د تقدير ليک وى. دا ډېر د پخوا نه معلومه وه چې د هر يو کس سره به څۀ کيږى. نو خُدائ پاک سره د دې موضوع په حقله بحث کول فضول دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16438, 'Ecclesiastes 6:11', 'Ecclesiastes', 6, 11, '&nbsp;څومره چې خبرې زياتيږى، نو دومره بې‌مطلبه کيږى، نو د بحث نه فائده څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16439, 'Ecclesiastes 6:12', 'Ecclesiastes', 6, 12, '&nbsp;نو چا ته څۀ پته وى چې زمونږ په دې لنډ او بې‌فائدې ژوند کښې، زمونږ دپاره څۀ ښۀ دى، داسې ژوند چې د سورى په شان تېريږى؟ چا ته دا پته ده چې د مرګ نه پس به څۀ کيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16440, 'Ecclesiastes 7:1', 'Ecclesiastes', 7, 1, '&nbsp;نېک نامى د قيمتى عطرو نه بهتره ده، او د مرګ ورځ د پېدا کېدو د ورځې نه بهتره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16441, 'Ecclesiastes 7:2', 'Ecclesiastes', 7, 2, '&nbsp;ښۀ دا ده چې هغه کور ته لاړ شُو چرته چې ماتم کيږى نه چې هغه کور ته لاړ شُو چرته چې دعوت وى، ځکه چې ژوندو خلقو له دا خبره په ذهن کښې کښېنول په کار دى چې مرګ زمونږ د ټولو انتظار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16442, 'Ecclesiastes 7:3', 'Ecclesiastes', 7, 3, '&nbsp;د خندا نه غم ښۀ وى، غمژن مخ د زړۀ د بهترۍ سبب جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16443, 'Ecclesiastes 7:4', 'Ecclesiastes', 7, 4, '&nbsp;هوښيار کس د مرګ په حقله ډېر فکر کوى، خو کم عقل صرف د عېش عشرت په حقله فکر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16444, 'Ecclesiastes 7:5', 'Ecclesiastes', 7, 5, '&nbsp;ښۀ خبره دا ده چې هوښيار دې ورَټى په ځائ د دې نه چې د کم عقلو خلقو د خوشامندۍ سندرې واورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16445, 'Ecclesiastes 7:6', 'Ecclesiastes', 7, 6, '&nbsp;د کم عقل خندا داسې وى لکه چې دېګچى لاندې په اور کښې ازغى ټسيږى. دا شور خو جوړوى خو هيڅ مقصد يې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16446, 'Ecclesiastes 7:7', 'Ecclesiastes', 7, 7, '&nbsp;ناروا ګټه هوښيارو خلقو نه کم عقل جوړوى، او رشوت اخستل ضمير خرابوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16447, 'Ecclesiastes 7:8', 'Ecclesiastes', 7, 8, '&nbsp;د څۀ سر ته رسول د هغې د شروع نه ښۀ وى، او د غرور کولو نه صبر کول ښۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16448, 'Ecclesiastes 7:9', 'Ecclesiastes', 7, 9, '&nbsp;خپله غصه په قابو کښې ساته، ځکه چې د کم عقل دماغ د غصې کور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16449, 'Ecclesiastes 7:10', 'Ecclesiastes', 7, 10, '&nbsp;هيڅکله داسې مۀ وايه، ”تېر وخت د اوس نه ښۀ وو.“ دا خبره کول عقلمندى نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16450, 'Ecclesiastes 7:11', 'Ecclesiastes', 7, 11, '&nbsp;هوښيار جوړېدل ښۀ دى. دا داسې دى لکه چې ميراث واخلى. په دُنيا کښې د هر چا دپاره عقلمند جوړېدل فائده مند دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16451, 'Ecclesiastes 7:12', 'Ecclesiastes', 7, 12, '&nbsp;عقلمندى به دې د پېسو په شان حِفاظت کوى. او د عقلمندۍ خاص فائده دا ده چې هغه خپل مالِک محفوظ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16452, 'Ecclesiastes 7:13', 'Ecclesiastes', 7, 13, '&nbsp;د خُدائ پاک په کارونو باندې فکر وکړه، څۀ چې هغۀ کاږۀ جوړ کړى وى نو هغه څوک نېغولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16453, 'Ecclesiastes 7:14', 'Ecclesiastes', 7, 14, '&nbsp;په ښۀ حالاتو کښې خوشحاله اوسئ، خو چې کله تکليف راځى، نو ياد ساته چې خوشحالى او تکليف، دواړه خُدائ پاک راولى، او هيچا ته پته نۀ لګى چې سبا به څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16454, 'Ecclesiastes 7:15', 'Ecclesiastes', 7, 15, '&nbsp;ما په خپل بې‌فائدې ژوند کښې هر څۀ ليدلى دى، يو صادق باوجود د خپل صداقت نه هم تباه شى او يو بدعمله په خپله بدعملۍ کښې اوږد عُمر تېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16455, 'Ecclesiastes 7:16', 'Ecclesiastes', 7, 16, '&nbsp;د ځان نه ډېر ايمانداره مۀ جوړوه او د ځان نه ډېر هوښيار سړے مۀ جوړوه، ولې ځان تباه کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16456, 'Ecclesiastes 7:17', 'Ecclesiastes', 7, 17, '&nbsp;خو دې سره د ځان نه ډېر بدعمله يا کم عقل هم مۀ جوړوه، نو په داسې کولو سره ولې خپل ځان د وخت نه مخکښې په چا وژنې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16457, 'Ecclesiastes 7:18', 'Ecclesiastes', 7, 18, '&nbsp;ښۀ خبره دا ده چې دا دواړه خبرې هېرې نۀ کړې، ځکه څوک چې د خُدائ پاک نه يريږى، هغوئ به د دواړو خطرو نه بچ پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16458, 'Ecclesiastes 7:19', 'Ecclesiastes', 7, 19, '&nbsp;حِکمت هوښيار سړے د ښار د لسو حکمرانانو نه زيات طاقتور جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16459, 'Ecclesiastes 7:20', 'Ecclesiastes', 7, 20, '&nbsp;په دې دُنيا کښې داسې هيڅ څوک صادق نشته چې هغه همېشه ښۀ کوى او هيڅکله ګناه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16460, 'Ecclesiastes 7:21', 'Ecclesiastes', 7, 21, '&nbsp;خلق چې څۀ وائى نو هغه هر څيز زړۀ ته مۀ اچوه، ګنې وابه ورې چې ستا نوکر تا پسې کنځل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16461, 'Ecclesiastes 7:22', 'Ecclesiastes', 7, 22, '&nbsp;او تا ته پته ده چې څو څو ځلې تا په خپله نورو خلقو ته کنځلې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16462, 'Ecclesiastes 7:23', 'Ecclesiastes', 7, 23, '&nbsp;ما د حِکمت اصُول استعمال کړل چې په دې هر څۀ باندې پوهه شم، خو دا زما دپاره ډېر ګران وُو، ما نۀ شول کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16463, 'Ecclesiastes 7:24', 'Ecclesiastes', 7, 24, '&nbsp;هر څۀ چې موجود دى هغه ډېر ژور او زما د پوهې نه بهر دى. څوک په هر څۀ پوهېدلے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16464, 'Ecclesiastes 7:25', 'Ecclesiastes', 7, 25, '&nbsp;ما کلکه فېصله وکړه چې د حِکمت مطالعه وکړم او د څيزونو په اسبابو باندې پوهه شم، او چې زده کړم چې بدعملى څومره بې‌وقوفتوب دے، او بې‌وقوفتوب څومره پاګلتوب دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16465, 'Ecclesiastes 7:26', 'Ecclesiastes', 7, 26, '&nbsp;ما ته پته ولګېده چې ګېروونکې ښځه د مرګ د سختۍ نه هم لوئ دام دے. د هغې شوق د دام په شان دے او د هغې غېږه د زنځيرونو په شان ده. کوم سړے چې خُدائ پاک رضا کوى نو هغه به ترې نه خلاص وى، خو ګناهګار به د هغې په جال کښې راګېريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16466, 'Ecclesiastes 7:27', 'Ecclesiastes', 7, 27, '&nbsp;معلِم وفرمائيل چې زۀ دې نتيجې ته ورسېدم، کله چې ما په دې موضوع باندې د هر طرف نه غور و فکر وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16467, 'Ecclesiastes 7:28', 'Ecclesiastes', 7, 28, '&nbsp;اګر چې ما بار بار لټون کولو خو ما هغه څۀ پېدا نۀ کړل څۀ چې ما لټول. ما په زرو کسانو کښې يو نېک سړے پېدا کړو، خو يوه نېکه ښځه مې پکښې پېدا نۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16468, 'Ecclesiastes 7:29', 'Ecclesiastes', 7, 29, '&nbsp;نو زۀ صرف دې نتيجې ته ورسېدم چې خُدائ پاک انسان پېدا کړے دے چې نېک وى، خو هغه په نورو ډېرو منصوبو پسې ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16469, 'Ecclesiastes 8:1', 'Ecclesiastes', 8, 1, '&nbsp;څوک د هوښيار په شان دے؟ څوک د خبرو د صحيح تشريح عِلم لرى؟ حِکمت د هغوئ مخونه روښانه کوى او د هغوئ سخت مزاج نرموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16470, 'Ecclesiastes 8:2', 'Ecclesiastes', 8, 2, '&nbsp;زۀ وايم، د بادشاه حُکم منه، ځکه چې تا د خُدائ پاک سره د دې وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16471, 'Ecclesiastes 8:3', 'Ecclesiastes', 8, 3, '&nbsp;د بادشاه په حضور کښې د تلو نه جلدى مۀ کوه. او په بد کار کښې حِصه مۀ اخله، ځکه چې بادشاه درسره څۀ غواړى هغه کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16472, 'Ecclesiastes 8:4', 'Ecclesiastes', 8, 4, '&nbsp;ځکه چې د بادشاه خبره وزن وى او هيڅ څوک ترې نه دا تپوس نۀ شى کولے چې، ”تۀ څۀ کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16473, 'Ecclesiastes 8:5', 'Ecclesiastes', 8, 5, '&nbsp;هغه کس څوک چې شاهى حُکم منى هغوئ ته به سزا نۀ ملاويږى. هوښيار کس د هر څيز په وخت او سبب باندې پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16474, 'Ecclesiastes 8:6', 'Ecclesiastes', 8, 6, '&nbsp;ځکه چې د هر څيز دپاره يو وخت او يوه طريقه وى، خو انسان له ډېر غمونه برداشت کول په کار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16475, 'Ecclesiastes 8:7', 'Ecclesiastes', 8, 7, '&nbsp;هيچا ته پته نشته چې څۀ به کيږى، نو بيا څوک دا وئيلے شى چې په مستقبل کښې څۀ کېدو والا دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16476, 'Ecclesiastes 8:8', 'Ecclesiastes', 8, 8, '&nbsp;هيڅ څوک خپل ځان د مرګ نه نۀ شى بچ کولے او نۀ څوک د اجل ورځ وروستو کولے شى. دا يو داسې جنګ دے چې مونږ ترې نه نۀ شُو خلاصېدلے، او بدعملى يو بدعمله کس د مرګ نه نۀ شى بچ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16477, 'Ecclesiastes 8:9', 'Ecclesiastes', 8, 9, '&nbsp;ما ټولو څيزونو ته غور سره وکتل او په مخ د زمکې چې څۀ کيږى د هغې په حقله مې سوچ وکړو، خلق په نورو خلقو باندې اختيار لرى او ورته نقصان رسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16478, 'Ecclesiastes 8:10', 'Ecclesiastes', 8, 10, '&nbsp;آو، ما وليدل چې بدعمله د عزت سره ښخ شوى وُو او هغوئ به د خُدائ پاک مقدس کور ته تلل راتلل، خو چې په کومو ښارونو کښې هغوئ بدعملى کوله نو هلته خلقو د هغوئ صِفت بيانولو. دا هم بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16479, 'Ecclesiastes 8:11', 'Ecclesiastes', 8, 11, '&nbsp;د بدو عملونو سزا زر نۀ ورکولے کيږى، نو ځکه د خلقو زړونه بدعملۍ ته تيار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16480, 'Ecclesiastes 8:12', 'Ecclesiastes', 8, 12, '&nbsp;د يو ګناهګار نه سل ځله ګناه کيږى خو بيا هم تر ډېره وخته پورې ژوندے وى. بې‌شکه ما ته دا هم پته ده چې کوم خلق د خُدائ پاک نه يريږى هغوئ به په خير خيريت سره ژوند کوى، يعنې هغه خلق د چا په زړۀ کښې چې د خُدائ پاک يره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16481, 'Ecclesiastes 8:13', 'Ecclesiastes', 8, 13, '&nbsp;او د بدعمله خلقو به خير نۀ وى او نۀ به يې ژوند اوږد وى. او دا ځکه چې هغوئ د خُدائ پاک نه نۀ يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16482, 'Ecclesiastes 8:14', 'Ecclesiastes', 8, 14, '&nbsp;خو په مخ د زمکې يوه بله خبره هم ده چې بې‌معنې ده. ښو خلقو ته داسې سزا ملاويږى لکه چې هغوئ بدعمله وى او بدعمله خلقو ته داسې اجر ملاويږى لکه چې هغوئ ښۀ خلق وى. نو زۀ تاسو ته دا وايم چې دا بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16483, 'Ecclesiastes 8:15', 'Ecclesiastes', 8, 15, '&nbsp;نو زما مشوره دا ده چې مونږ له د ژوند نه خوند اخستل په کار دى، ځکه چې په دې ژوند کښې هم دا يوه مزه ده چې خوراک څښاک کوُو او خوشحاله اوسو. نو داسې سخت محنت، کوم چې په مخ د زمکې خُدائ پاک مونږ له راکړے دے هغې سره سره څۀ لږه خوشحالى هم وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16484, 'Ecclesiastes 8:16', 'Ecclesiastes', 8, 16, '&nbsp;کله چې ما پوره کوشش وکړو چې هوښيار شم او په هغې کار غور وکړم چې خلق يې د زمکې په مخ کوى، نو ما وکتل چې د داسې محنت په وجه هغوئ شپه او ورځ خوب نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16485, 'Ecclesiastes 8:17', 'Ecclesiastes', 8, 17, '&nbsp;نو ما ته پته ولګېده چې خُدائ پاک په دُنيا کښې څۀ کوى نو هيچا ته هم د هغې پته نۀ لګى. کېدے شى چې يو هوښيار کس دا دعوىٰ وکړى چې زۀ په دې پوره پوهه شوم، خو دا به داسې نۀ وى، هغه د دې اَنجام ته نۀ شى رسېدے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16486, 'Ecclesiastes 9:1', 'Ecclesiastes', 9, 1, '&nbsp;اوس ما د دې هر څۀ مطالعه وکړه او دې نتيجې ته ورسېدم چې صادقان او هوښيار خلق چې هر څۀ کوى هغه د خُدائ پاک په لاس کښې دى. هغوئ ته دا پته نۀ لګى چې خُدائ پاک به يې قبلوى او کۀ رد کوى. دا هر څۀ به په راتلونکى وخت کښې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16487, 'Ecclesiastes 9:2', 'Ecclesiastes', 9, 2, '&nbsp;د صادق او د بدعمله، د ښۀ او د بد، د پاک او د ناپاک، هغه خلق چې خُدائ پاک ته قربانۍ پېش کوى يا هغه خلق چې قربانۍ نۀ پېش کوى، ټولو سره قسمت يو شان معامله کوى. د يو ښۀ کس او د ګناهګار يو شان اَنجام وى، د قسم خوړلو والا او د قسم نۀ خوړلو والا دواړو يو منزل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16488, 'Ecclesiastes 9:3', 'Ecclesiastes', 9, 3, '&nbsp;دا يو ډېر لوئ مصيبت دے چې په مخ د زمکې کيږى، د هر ژوندى هم يو قِسمت دے يعنې مرګ. د دې نه علاوه، د ټولو خلقو زړونه د بد کارۍ نۀ ډک دى او د ژوندون په دوران کښې د هغوئ په زړونو کښې بې‌وقوفتوب وى او بيا دوئ مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16489, 'Ecclesiastes 9:4', 'Ecclesiastes', 9, 4, '&nbsp;خو څوک چې تر اوسه پورې په ژوندو کښې شريک دى د هغوئ اُميد وى، ځکه چې يو ژوندے سپے د مړ ازمرى نه ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16490, 'Ecclesiastes 9:5', 'Ecclesiastes', 9, 5, '&nbsp;يقيناً چې ژوندو ته خو دومره پته وى چې هغوئ به مرى. خو مړو ته هيڅ پته نۀ لګى. هغوئ ته نور اجر نۀ ملاويږى، او د هغوئ يادونه ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16491, 'Ecclesiastes 9:6', 'Ecclesiastes', 9, 6, '&nbsp;د هغوئ مينه، نفرت او غېرت، هر څۀ ډېر مخکښې ختم شوى دى. په مخ د زمکې چې څۀ کيږى نو هغوئ به هيڅکله په کښې برخه وانۀ خلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16492, 'Ecclesiastes 9:7', 'Ecclesiastes', 9, 7, '&nbsp;نو بيا خوشحالۍ سره مے څښه او خپل خوراک کوه. ځکه چې خُدائ پاک د دې هر څۀ اجازت ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16493, 'Ecclesiastes 9:8', 'Ecclesiastes', 9, 8, '&nbsp;هر وخت سپينې جامې اغونده او تېل لګوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16494, 'Ecclesiastes 9:9', 'Ecclesiastes', 9, 9, '&nbsp;د خپلې ښځې سره چې تۀ ورسره مينه کوې د ژوند نه خوند اخله. په مخ د زمکې په فانى ژوندون کښې چې خُدائ پاک تا له څومره ورځې درکړې دى هغه هم دغه شان تېروه. ځکه چې په مخ د زمکې ستا د محنت مشقت په بدل کښې هم دغه څۀ دى چې ستا په نصيب کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16495, 'Ecclesiastes 9:10', 'Ecclesiastes', 9, 10, '&nbsp;تۀ چې هر څۀ کولے شې هغه پوره د زړۀ نه کوه، ځکه چې چرته تۀ روان يې يعنې قبر ته، هلته به نۀ کار وى او نۀ منصوبې، نۀ به عِلم وى او نۀ حِکمت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16496, 'Ecclesiastes 9:11', 'Ecclesiastes', 9, 11, '&nbsp;ما ته په دُنيا کښې د يو بل څيز هم پته ولګېده چې تېزه منډه وهونکى همېشه د منډې لوبه نۀ ګټى او تکړه جنګيالى همېشه جنګ نۀ شى ګټلے. هوښيار خلق هر وخت په رزق ماړۀ نۀ وى، قابل خلق همېشه نۀ مالداره کيږى او تعليم يافته خلق تل په ژوند کښې کامياب نۀ وى. هر څۀ په وخت او په بخت باندې منحصر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16497, 'Ecclesiastes 9:12', 'Ecclesiastes', 9, 12, '&nbsp;انسان ته هيڅکله دا پته نۀ لګى چې په هغۀ به سخت وخت کله راځى. لکه څنګه چې کبان په جال کښې او مارغان په دام کښې اچانک راګېر شى، نو داسې به مرګ انسان سمدستى راګېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16498, 'Ecclesiastes 9:13', 'Ecclesiastes', 9, 13, '&nbsp;ما ته په مخ د زمکې د حِکمت يو بل مثال مِلاو شوے دے او دا ما ته ډېر زيات ښۀ ښکارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16499, 'Ecclesiastes 9:14', 'Ecclesiastes', 9, 14, '&nbsp;يو وړوکے ښار وو چې آبادى يې لږه وه. يو طاقتور بادشاه په دې باندې حمله وکړه. هغه ښار يې محاصره کړو او په دېوالونو باندې د اوړېدو تيارے يې شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16500, 'Ecclesiastes 9:15', 'Ecclesiastes', 9, 15, '&nbsp;خو په هغه ښار کښې يو غريب خو هوښيار کس وو. هغۀ په خپلې هوښيارتيا سره هغه ښار بچ کړو. خو وروستو هيچا هغه ياد نۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');